CREATE POLICY "Public can view company logos" ON storage.objects FOR SELECT TO public USING (bucket_id = 'logos');
CREATE POLICY "Organization admins can upload company logos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'logos' AND (storage.foldername(name))[1] = public.get_user_org_id(auth.uid())::text AND public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Organization admins can update company logos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'logos' AND (storage.foldername(name))[1] = public.get_user_org_id(auth.uid())::text AND public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (bucket_id = 'logos' AND (storage.foldername(name))[1] = public.get_user_org_id(auth.uid())::text AND public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Organization admins can delete company logos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'logos' AND (storage.foldername(name))[1] = public.get_user_org_id(auth.uid())::text AND public.has_role(auth.uid(), 'admin'::public.app_role));